HTML = '<!doctype html>\n<html lang="fr">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>push_swap — Visualiseur</title>\n<style>\n:root{\n  --bg:#f2efe8;--panel:#fbfaf7;--ink:#171918;--muted:#74756f;--line:#d7d2c8;\n  --green:#243a34;--terracotta:#a86449;--ok:#3f7457;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}\nbutton,input,textarea{font:inherit}\nbutton{cursor:pointer}\n.wrap{width:min(1500px,calc(100% - 36px));margin:28px auto 44px}\n.head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:18px}\n.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);font-weight:700}\nh1{font:500 clamp(34px,4vw,58px)/1 Georgia,serif;letter-spacing:-.035em;margin:7px 0 0}\n.head-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.tag{border:1px solid var(--line);border-radius:999px;padding:8px 11px;background:#ffffff88;color:var(--muted);font-size:12px}\n.layout{display:grid;grid-template-columns:360px minmax(0,1fr);gap:18px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px}\n.side{padding:18px;display:flex;flex-direction:column;gap:20px}\n.label{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);font-weight:750;margin-bottom:8px}\ntextarea,input[type=text],input[type=number]{width:100%;border:1px solid var(--line);border-radius:11px;background:white;color:var(--ink);padding:11px 12px;outline:none}\ntextarea{min-height:92px;resize:vertical;font:12px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace}\ntextarea:focus,input:focus{border-color:#9e9c94;box-shadow:0 0 0 3px #424d470f}\n.row{display:flex;gap:8px;flex-wrap:wrap}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.btn{border:1px solid var(--line);border-radius:11px;background:white;color:var(--ink);padding:10px 13px;font-size:13px;font-weight:700}\n.btn:hover{background:#f4f2ed}.btn.primary{background:var(--ink);color:white;border-color:var(--ink)}\n.note,.status{font-size:12px;line-height:1.55;color:var(--muted)}.status.ok{color:var(--ok)}.status.err{color:#a34539}\n.algobox{border-top:1px solid var(--line);padding-top:16px}\n.algo-main{font:500 20px/1.15 Georgia,serif;margin:2px 0 5px}\n.algo-details{font-size:12px;color:var(--muted);line-height:1.5}\n.legend{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n.legend-item{display:flex;align-items:center;gap:5px;font-size:10px;color:var(--muted)}\n.swatch{width:10px;height:10px;border-radius:2px}\n\n.stage{min-height:760px;padding:18px;display:flex;flex-direction:column}\n.stage-head{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:14px;padding:5px 4px 14px;border-bottom:1px solid var(--line)}\n.stack-title{font:500 29px/1 Georgia,serif;display:flex;align-items:baseline;gap:9px}.stack-title.r{justify-content:flex-end}\n.count{font:700 10px/1.2 Inter,system-ui,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.op{text-align:center;min-width:180px}.op small{display:block;font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}\n.op strong{display:block;font:800 24px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;margin-top:4px}\n.phase{font-size:10px;color:var(--muted);margin-top:3px}\n.canvases{display:grid;grid-template-columns:minmax(0,1fr) 66px minmax(0,1fr);gap:10px;flex:1;padding:16px 0 10px;min-height:560px}\n.canvas-shell{position:relative;border-radius:14px;overflow:hidden;background:linear-gradient(180deg,#ffffffa8,#ece8df90);min-width:0}\ncanvas{display:block;width:100%;height:100%}\n.middle{display:flex;align-items:center;justify-content:center;position:relative}\n.middle::before{content:"";width:1px;height:100%;background:linear-gradient(transparent,var(--line) 10%,var(--line) 90%,transparent)}\n.middle span{position:absolute;transform:rotate(-90deg);font-size:9px;letter-spacing:.17em;text-transform:uppercase;color:#989993;background:var(--panel);padding:5px 9px;white-space:nowrap}\n\n.quick{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}\n.quick .btn{padding:7px 10px;font-size:11px}\n.playback{border-top:1px solid var(--line);padding-top:12px}\n.timeline{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px}\n.transport{display:flex;gap:6px}.icon{width:38px;height:38px;border:1px solid var(--line);border-radius:10px;background:white;font-weight:800}.icon.main{background:var(--ink);color:white;border-color:var(--ink)}\ninput[type=range]{width:100%;accent-color:var(--green)}.step{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--muted);white-space:nowrap}\n.meta{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:12px}\n.valid{display:flex;align-items:center;gap:7px}.dot{width:8px;height:8px;border-radius:50%;background:#aaa}.dot.ok{background:var(--ok)}.dot.bad{background:#a34539}\n.speed{display:flex;align-items:center;gap:8px}.speed input{width:120px}\n\nbody.capture .side,body.capture .head-actions,body.capture .transport,body.capture .speed,body.capture .quick{display:none!important}\nbody.capture .layout{grid-template-columns:1fr}\nbody.capture .wrap{width:min(1320px,calc(100% - 44px));margin-top:34px}\nbody.capture .stage{min-height:820px;padding:28px}\nbody.capture .canvases{min-height:630px}\nbody.capture .timeline{grid-template-columns:minmax(0,1fr) auto}\nbody.capture h1{font-size:54px}\n.capture-hint{display:none;position:fixed;right:18px;bottom:18px;background:#171918;color:white;padding:9px 12px;border-radius:10px;font-size:12px;opacity:.9}\nbody.capture .capture-hint{display:block}\n\n@media(max-width:920px){.layout{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column}.stage{min-height:700px}}\n@media(max-width:640px){.wrap{width:calc(100% - 20px);margin-top:14px}.stage{padding:12px}.canvases{grid-template-columns:minmax(0,1fr) 26px minmax(0,1fr);min-height:460px}.stack-title{font-size:21px}.op{min-width:90px}.op strong{font-size:19px}}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <header class="head">\n    <div>\n      <div class="kicker">42 · Algorithmique & optimisation</div>\n      <h1>push_swap — visualisation</h1>\n    </div>\n    <div class="head-actions">\n      <span class="tag" id="binaryTag">./push_swap</span>\n      <span class="tag" id="algoTag">—</span>\n      <button class="btn" id="captureBtn" type="button">Mode capture</button>\n    </div>\n  </header>\n\n  <div class="layout">\n    <aside class="card side">\n      <section>\n        <div class="label">Jeu de données</div>\n        <textarea id="numbers" spellcheck="false"></textarea>\n        <div class="row" style="margin-top:9px">\n          <button class="btn primary" id="runBtn" type="button">Exécuter push_swap</button>\n          <button class="btn" id="exampleBtn" type="button">100 valeurs</button>\n        </div>\n      </section>\n\n      <section>\n        <div class="label">Génération reproductible</div>\n        <div class="grid2">\n          <label><span class="note">Taille · 2 à 1000</span><input id="size" type="number" min="2" max="1000" value="100"></label>\n          <label><span class="note">Seed</span><input id="seed" type="text" value="portfolio"></label>\n        </div>\n        <button class="btn" id="generateBtn" type="button" style="width:100%;margin-top:9px">Générer une permutation</button>\n        <div class="note" style="margin-top:7px">La génération utilise une permutation de <code>0…N-1</code>, sans doublon. C\'est plus adapté pour observer les pivots/chunks de ton implémentation.</div>\n      </section>\n\n      <section class="algobox">\n        <div class="label">Stratégie détectée</div>\n        <div class="algo-main" id="algoMain">—</div>\n        <div class="algo-details" id="algoDetails">Lance le programme pour afficher la stratégie correspondant à la taille.</div>\n        <div class="legend" id="legend"></div>\n      </section>\n\n      <section>\n        <div class="label">État</div>\n        <div class="status" id="status">Prêt.</div>\n      </section>\n    </aside>\n\n    <main class="card stage">\n      <div class="stage-head">\n        <div class="stack-title">Stack A <span class="count" id="countA">0 éléments</span></div>\n        <div class="op">\n          <small>Opération</small>\n          <strong id="currentOp">—</strong>\n          <div class="phase" id="phase">—</div>\n        </div>\n        <div class="stack-title r"><span class="count" id="countB">0 éléments</span> Stack B</div>\n      </div>\n\n      <div class="canvases">\n        <div class="canvas-shell"><canvas id="canvasA"></canvas></div>\n        <div class="middle"><span>top → bottom</span></div>\n        <div class="canvas-shell"><canvas id="canvasB"></canvas></div>\n      </div>\n\n      <div class="quick">\n        <button class="btn" id="halfBtn" type="button">Mi-distribution</button>\n        <button class="btn" id="peakBtn" type="button">Pic de Stack B</button>\n        <button class="btn" id="startBtn" type="button">Début</button>\n        <button class="btn" id="endBtn" type="button">Fin</button>\n      </div>\n\n      <div class="playback">\n        <div class="timeline">\n          <div class="transport">\n            <button class="icon" id="prevBtn" type="button">‹</button>\n            <button class="icon main" id="playBtn" type="button">▶</button>\n            <button class="icon" id="nextBtn" type="button">›</button>\n          </div>\n          <input id="timeline" type="range" min="0" max="0" value="0">\n          <span class="step" id="stepText">0 / 0</span>\n        </div>\n        <div class="meta">\n          <div class="valid"><span class="dot" id="dot"></span><span id="validText">Aucune exécution</span></div>\n          <div class="speed"><span>Vitesse</span><input id="speed" type="range" min="40" max="680" value="560" step="10"></div>\n        </div>\n      </div>\n    </main>\n  </div>\n</div>\n<div class="capture-hint">Échap pour quitter le mode capture</div>\n\n<script>\n(() => {\n  const $=s=>document.querySelector(s);\n  const e={\n    numbers:$(\'#numbers\'),size:$(\'#size\'),seed:$(\'#seed\'),run:$(\'#runBtn\'),example:$(\'#exampleBtn\'),generate:$(\'#generateBtn\'),\n    status:$(\'#status\'),a:$(\'#canvasA\'),b:$(\'#canvasB\'),ca:$(\'#countA\'),cb:$(\'#countB\'),op:$(\'#currentOp\'),phase:$(\'#phase\'),\n    prev:$(\'#prevBtn\'),next:$(\'#nextBtn\'),play:$(\'#playBtn\'),timeline:$(\'#timeline\'),step:$(\'#stepText\'),speed:$(\'#speed\'),\n    dot:$(\'#dot\'),valid:$(\'#validText\'),capture:$(\'#captureBtn\'),binary:$(\'#binaryTag\'),algoTag:$(\'#algoTag\'),\n    algoMain:$(\'#algoMain\'),algoDetails:$(\'#algoDetails\'),legend:$(\'#legend\'),\n    half:$(\'#halfBtn\'),peak:$(\'#peakBtn\'),start:$(\'#startBtn\'),end:$(\'#endBtn\')\n  };\n\n  const COLORS=[\'#243a34\',\'#6b8178\',\'#a86449\',\'#c48968\',\'#6b7483\',\'#9b8e70\',\'#765b66\',\'#8f9a8d\',\'#b07159\',\'#526967\',\'#917b67\',\'#68778c\'];\n  const CHECKPOINT=200;\n\n  let source=[],ops=[],idx=0,state={a:[],b:[]},checkpoints=new Map(),timer=null;\n  let meta=null,maxBStep=0,halfStep=0,firstPa=-1,finalValid=false;\n\n  const setStatus=(m,k=\'\')=>{e.status.textContent=m;e.status.className=\'status \'+k};\n\n  function parse(raw){\n    const p=raw.trim().split(/[\\s,;]+/).filter(Boolean);\n    if(p.length<2)throw Error(\'Entre au moins deux nombres.\');\n    const n=p.map(v=>{\n      if(!/^-?\\d+$/.test(v))throw Error(\'Valeur invalide : \'+v);\n      const x=Number(v);\n      if(!Number.isSafeInteger(x)||x<-2147483648||x>2147483647)throw Error(\'Valeur hors int32 : \'+v);\n      return x;\n    });\n    if(new Set(n).size!==n.length)throw Error(\'Les doublons ne sont pas autorisés.\');\n    if(n.length>1000)throw Error(\'Maximum 1000 valeurs.\');\n    return n;\n  }\n\n  function hash(s){let h=1779033703^s.length;for(let i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),3432918353);h=h<<13|h>>>19}return()=>{h=Math.imul(h^(h>>>16),2246822507);h=Math.imul(h^(h>>>13),3266489909);return(h^=h>>>16)>>>0}}\n  function rng(a){return()=>{let t=a+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}\n\n  function generate(){\n    const n=Math.max(2,Math.min(1000,Number(e.size.value)||100));e.size.value=n;\n    const r=rng(hash(e.seed.value||\'portfolio\')());\n    const arr=Array.from({length:n},(_,i)=>i);\n    for(let i=arr.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}\n    e.numbers.value=arr.join(\' \');\n  }\n\n  function defineChunks(n){\n    if(n<100)return 1;\n    if(n<300)return 3;\n    if(n<600)return 6;\n    return Math.floor(n/100);\n  }\n\n  function exactPivots(nums,chunks){\n    const arr=nums.slice().sort((a,b)=>a-b);\n    if(chunks===1)return [Math.floor(nums.length/2)]; // fidèle au C actuel\n    const pivots=new Array(chunks*2-2);\n    const base=Math.floor(nums.length/chunks);\n    pivots[0]=arr[base];\n    pivots[1]=arr[base*2];\n    let j=3,i=2;\n    while(i<(chunks*2)-2){\n      if(i===(chunks*2)-4){\n        pivots[i]=arr[nums.length-Math.floor(base/2)];\n        pivots[i+1]=arr[nums.length-1];\n        i+=2;\n      }else if(i%2===1){\n        pivots[i]=arr[base*j];i++;j++;\n      }else{\n        pivots[i]=arr[(base*j)-Math.floor(base/2)];i++;\n      }\n    }\n    return pivots;\n  }\n\n  function analyse(nums){\n    const n=nums.length,chunks=defineChunks(n);\n    let mode;\n    if(n===2)mode=\'Cas spécialisé · 2 éléments\';\n    else if(n===3)mode=\'Tri spécialisé · 3 éléments\';\n    else if(chunks===1)mode=\'Distribution · chunk unique\';\n    else mode=`Distribution papillon · ${chunks} chunks`;\n    return {n,chunks,mode,pivots:exactPivots(nums,chunks),sorted:nums.slice().sort((a,b)=>a-b)};\n  }\n\n  function chunkOf(v){\n    if(!meta||meta.chunks<=1)return 0;\n    let lo=0,hi=meta.sorted.length-1;\n    while(lo<=hi){const m=(lo+hi)>>1;if(meta.sorted[m]<v)lo=m+1;else if(meta.sorted[m]>v)hi=m-1;else{lo=m;break}}\n    return Math.min(meta.chunks-1,Math.floor(lo/(meta.n/meta.chunks)));\n  }\n\n  function apply(st,op){\n    const a=st.a.slice(),b=st.b.slice();\n    const sw=s=>{if(s.length>1)[s[0],s[1]]=[s[1],s[0]]};\n    const pu=(f,t)=>{if(f.length)t.unshift(f.shift())};\n    const ro=s=>{if(s.length>1)s.push(s.shift())};\n    const rr=s=>{if(s.length>1)s.unshift(s.pop())};\n    switch(op){\n      case\'sa\':sw(a);break;case\'sb\':sw(b);break;case\'ss\':sw(a);sw(b);break;\n      case\'pa\':pu(b,a);break;case\'pb\':pu(a,b);break;\n      case\'ra\':ro(a);break;case\'rb\':ro(b);break;case\'rr\':ro(a);ro(b);break;\n      case\'rra\':rr(a);break;case\'rrb\':rr(b);break;case\'rrr\':rr(a);rr(b);break;\n      default:throw Error(\'Opération inconnue : \'+op)\n    }\n    return{a,b};\n  }\n\n  function cloneState(s){return{a:s.a.slice(),b:s.b.slice()}}\n\n  function buildIndex(){\n    checkpoints=new Map();\n    let st={a:source.slice(),b:[]};\n    checkpoints.set(0,cloneState(st));\n    let maxB=0,halfBest=Infinity;\n    maxBStep=0;halfStep=0;firstPa=-1;\n    const target=source.length/2;\n\n    for(let i=0;i<ops.length;i++){\n      st=apply(st,ops[i]);\n      const step=i+1;\n      if(firstPa<0&&ops[i]===\'pa\')firstPa=step;\n      if(st.b.length>maxB){maxB=st.b.length;maxBStep=step}\n      if(firstPa<0){\n        const d=Math.abs(st.b.length-target);\n        if(d<halfBest){halfBest=d;halfStep=step}\n      }\n      if(step%CHECKPOINT===0)checkpoints.set(step,cloneState(st));\n    }\n    checkpoints.set(ops.length,cloneState(st));\n    finalValid=isSorted(st);\n  }\n\n  function isSorted(st){\n    if(st.b.length)return false;\n    for(let i=1;i<st.a.length;i++)if(st.a[i-1]>st.a[i])return false;\n    return true;\n  }\n\n  function seek(target){\n    target=Math.max(0,Math.min(ops.length,target));\n    if(target===idx)return;\n\n    if(target>idx && target-idx<=80){\n      let st=state;\n      for(let i=idx;i<target;i++)st=apply(st,ops[i]);\n      state=st;idx=target;render();return;\n    }\n\n    let cp=Math.floor(target/CHECKPOINT)*CHECKPOINT;\n    while(!checkpoints.has(cp)&&cp>0)cp-=CHECKPOINT;\n    state=cloneState(checkpoints.get(cp)||{a:source.slice(),b:[]});\n    for(let i=cp;i<target;i++)state=apply(state,ops[i]);\n    idx=target;render();\n  }\n\n  function phaseLabel(){\n    if(!ops.length)return \'—\';\n    if(idx===0)return \'État initial\';\n    if(firstPa<0||idx<firstPa){\n      return meta.chunks>1?\'Distribution A → B · chunks / papillon\':\'Distribution A → B · chunk unique\';\n    }\n    return \'Reconstruction B → A · coût de rotation minimal\';\n  }\n\n  function setupCanvas(canvas){\n    const rect=canvas.getBoundingClientRect();\n    const dpr=Math.min(window.devicePixelRatio||1,2);\n    const w=Math.max(1,Math.floor(rect.width*dpr)),h=Math.max(1,Math.floor(rect.height*dpr));\n    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}\n    const ctx=canvas.getContext(\'2d\');\n    ctx.setTransform(dpr,0,0,dpr,0,0);\n    return {ctx,w:rect.width,h:rect.height};\n  }\n\n  function draw(canvas,arr,side){\n    const {ctx,w,h}=setupCanvas(canvas);\n    ctx.clearRect(0,0,w,h);\n    const padX=18,padY=22,usableW=w-padX*2,usableH=h-padY*2;\n    if(!source.length)return;\n\n    const sorted=meta.sorted,min=sorted[0],max=sorted[sorted.length-1];\n    const count=arr.length;\n    const rowH=count?usableH/count:usableH;\n    const lineH=Math.max(.7,Math.min(10,rowH*.72));\n    const showValues=count<=45;\n\n    // chunk guides\n    if(meta.chunks>1){\n      ctx.save();\n      ctx.globalAlpha=.055;\n      for(let c=0;c<meta.chunks;c++){\n        ctx.fillStyle=COLORS[c%COLORS.length];\n        const x=side===\'a\'?padX+(usableW/meta.chunks)*c:padX+(usableW/meta.chunks)*(meta.chunks-1-c);\n        ctx.fillRect(x,padY,usableW/meta.chunks,usableH);\n      }\n      ctx.restore();\n    }\n\n    arr.forEach((v,i)=>{\n      const norm=max===min?.75:(v-min)/(max-min);\n      const bw=Math.max(3,usableW*(.07+.88*norm));\n      const y=padY+i*rowH+(rowH-lineH)/2;\n      ctx.fillStyle=meta.chunks>1?COLORS[chunkOf(v)%COLORS.length]:(side===\'a\'?\'#243a34\':\'#a86449\');\n      if(side===\'a\')ctx.fillRect(padX,y,bw,lineH);\n      else ctx.fillRect(w-padX-bw,y,bw,lineH);\n\n      if(showValues){\n        ctx.fillStyle=\'#171918\';\n        ctx.font=\'10px Inter, system-ui, sans-serif\';\n        ctx.textBaseline=\'middle\';\n        const ty=y+lineH/2;\n        if(side===\'a\'){ctx.textAlign=\'left\';ctx.fillText(String(v),Math.min(w-28,padX+bw+6),ty)}\n        else{ctx.textAlign=\'right\';ctx.fillText(String(v),Math.max(28,w-padX-bw-6),ty)}\n      }\n    });\n\n    ctx.strokeStyle=\'#d7d2c8\';ctx.lineWidth=1;\n    ctx.beginPath();ctx.moveTo(padX,h-padY+2);ctx.lineTo(w-padX,h-padY+2);ctx.stroke();\n\n    ctx.fillStyle=\'#8b8d87\';ctx.font=\'9px Inter, system-ui, sans-serif\';ctx.textBaseline=\'top\';\n    ctx.textAlign=side===\'a\'?\'left\':\'right\';\n    ctx.fillText(\'TOP\',side===\'a\'?padX:w-padX,5);\n  }\n\n  function renderMeta(){\n    if(!meta)return;\n    e.algoTag.textContent=meta.chunks>1?`${meta.chunks} chunks`:\'1 chunk\';\n    e.algoMain.textContent=meta.mode;\n\n    if(meta.n<=3){\n      e.algoDetails.textContent=\'Le programme utilise un traitement dédié à cette petite taille.\';\n    }else if(meta.chunks===1){\n      e.algoDetails.textContent=`Taille ${meta.n} : push_one_chunk(), puis reconstruction de B vers A par coût minimal.`;\n    }else{\n      const p=meta.pivots;\n      const preview=p.length<=8?p.join(\' · \'):`${p.slice(0,4).join(\' · \')} … ${p.slice(-3).join(\' · \')}`;\n      e.algoDetails.textContent=`Taille ${meta.n} : push_b() avec ${meta.chunks} chunks. Pivots calculés : ${preview}. Les couleurs représentent les groupes de rangs utilisés pour rendre la distribution visible.`;\n    }\n\n    e.legend.innerHTML=\'\';\n    if(meta.chunks>1){\n      for(let c=0;c<meta.chunks;c++){\n        const d=document.createElement(\'div\');d.className=\'legend-item\';\n        const s=document.createElement(\'span\');s.className=\'swatch\';s.style.background=COLORS[c%COLORS.length];\n        const t=document.createElement(\'span\');t.textContent=`C${c+1}`;\n        d.append(s,t);e.legend.appendChild(d);\n      }\n    }\n  }\n\n  function render(){\n    if(!source.length)return;\n    e.ca.textContent=`${state.a.length} élément${state.a.length!==1?\'s\':\'\'}`;\n    e.cb.textContent=`${state.b.length} élément${state.b.length!==1?\'s\':\'\'}`;\n    e.op.textContent=idx===0?\'START\':ops[idx-1];\n    e.phase.textContent=phaseLabel();\n    e.timeline.max=ops.length;e.timeline.value=idx;e.step.textContent=`${idx} / ${ops.length}`;\n    e.dot.className=\'dot \'+(finalValid?\'ok\':\'bad\');\n    e.valid.textContent=finalValid?`Tri validé · ${ops.length} opérations`:\'Résultat non trié\';\n    draw(e.a,state.a,\'a\');draw(e.b,state.b,\'b\');\n  }\n\n  function stop(){if(timer)clearInterval(timer);timer=null;e.play.textContent=\'▶\'}\n  function play(){\n    if(!source.length||!ops.length)return;\n    if(timer){stop();return}\n    if(idx>=ops.length)seek(0);\n    e.play.textContent=\'Ⅱ\';\n    const delay=Math.max(12,700-Number(e.speed.value));\n    timer=setInterval(()=>{if(idx>=ops.length){stop();return}seek(idx+1)},delay);\n  }\n\n  async function run(){\n    stop();let nums;\n    try{nums=parse(e.numbers.value)}catch(err){setStatus(err.message,\'err\');return}\n    e.run.disabled=true;setStatus(`Exécution de push_swap sur ${nums.length} valeurs…`);\n    try{\n      const r=await fetch(\'/api/run\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({numbers:nums})});\n      const data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||\'Erreur inconnue\');\n      source=nums;ops=data.operations;meta=analyse(nums);idx=0;state={a:source.slice(),b:[]};\n      e.binary.textContent=data.binary;\n      buildIndex();renderMeta();render();\n      setStatus(`${ops.length} opérations récupérées · ${meta.chunks} chunk${meta.chunks>1?\'s\':\'\'}.`,\'ok\');\n    }catch(err){setStatus(err.message,\'err\')}finally{e.run.disabled=false}\n  }\n\n  e.generate.addEventListener(\'click\',generate);\n  e.example.addEventListener(\'click\',()=>{e.size.value=100;e.seed.value=\'portfolio\';generate()});\n  e.run.addEventListener(\'click\',run);\n  e.prev.addEventListener(\'click\',()=>{stop();seek(idx-1)});\n  e.next.addEventListener(\'click\',()=>{stop();seek(idx+1)});\n  e.play.addEventListener(\'click\',play);\n  e.timeline.addEventListener(\'input\',()=>{stop();seek(Number(e.timeline.value))});\n  e.speed.addEventListener(\'input\',()=>{if(timer){stop();play()}});\n  e.half.addEventListener(\'click\',()=>{stop();seek(halfStep)});\n  e.peak.addEventListener(\'click\',()=>{stop();seek(maxBStep)});\n  e.start.addEventListener(\'click\',()=>{stop();seek(0)});\n  e.end.addEventListener(\'click\',()=>{stop();seek(ops.length)});\n  e.capture.addEventListener(\'click\',()=>{document.body.classList.toggle(\'capture\');e.capture.textContent=document.body.classList.contains(\'capture\')?\'Quitter le mode capture\':\'Mode capture\';requestAnimationFrame(render)});\n  window.addEventListener(\'resize\',()=>requestAnimationFrame(render));\n\n  document.addEventListener(\'keydown\',ev=>{\n    if(ev.key===\'Escape\'&&document.body.classList.contains(\'capture\')){document.body.classList.remove(\'capture\');e.capture.textContent=\'Mode capture\';requestAnimationFrame(render)}\n    if([\'INPUT\',\'TEXTAREA\'].includes(document.activeElement.tagName))return;\n    if(ev.key===\'ArrowLeft\'){stop();seek(idx-1)}\n    if(ev.key===\'ArrowRight\'){stop();seek(idx+1)}\n    if(ev.key===\' \'){ev.preventDefault();play()}\n  });\n\n  generate();\n})();\n</script>\n</body>\n</html>\n'

class Handler(BaseHTTPRequestHandler):
    def _json(self,obj,status=200):
        data=json.dumps(obj,ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type","application/json; charset=utf-8")
        self.send_header("Content-Length",str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if urlparse(self.path).path in ("/","/index.html"):
            data=HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type","text/html; charset=utf-8")
            self.send_header("Content-Length",str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        else:
            self.send_error(404)

    def do_POST(self):
        if urlparse(self.path).path!="/api/run":
            self.send_error(404);return
        try:
            length=int(self.headers.get("Content-Length","0"))
            if length>512000:
                self._json({"ok":False,"error":"Requête trop volumineuse."},413);return
            body=json.loads(self.rfile.read(length) or b"{}")
            nums=body.get("numbers")

            if not isinstance(nums,list) or not (2<=len(nums)<=1000):
                raise ValueError("Utilise entre 2 et 1000 valeurs.")
            if any(type(x) is not int for x in nums):
                raise ValueError("Toutes les valeurs doivent être des entiers.")
            if len(set(nums))!=len(nums):
                raise ValueError("Les doublons ne sont pas autorisés.")
            if any(x < -2147483648 or x > 2147483647 for x in nums):
                raise ValueError("Une valeur dépasse la plage int32.")

            binary=self.server.push_swap
            if not binary.is_file():
                raise FileNotFoundError(f"Binaire introuvable : {binary}. Lance d'abord `make`.")
            if not os.access(binary,os.X_OK):
                raise PermissionError(f"Le fichier n'est pas exécutable : {binary}")

            p=subprocess.run(
                [str(binary),*map(str,nums)],
                cwd=self.server.repo_dir,
                capture_output=True,text=True,timeout=60
            )
            if p.returncode!=0:
                raise RuntimeError((p.stderr or p.stdout or "push_swap a retourné une erreur.").strip()[:2000])

            ops=[x.strip() for x in p.stdout.splitlines() if x.strip()]
            allowed={"sa","sb","ss","pa","pb","ra","rb","rr","rra","rrb","rrr"}
            bad=[x for x in ops if x not in allowed]
            if bad:
                raise RuntimeError(f"Sortie inattendue de push_swap : {bad[0]}")

            self._json({"ok":True,"binary":str(binary),"operations":ops,"operation_count":len(ops)})
        except subprocess.TimeoutExpired:
            self._json({"ok":False,"error":"push_swap a dépassé le délai de 60 secondes."},408)
        except (ValueError,FileNotFoundError,PermissionError,RuntimeError) as exc:
            self._json({"ok":False,"error":str(exc)},400)
        except Exception as exc:
            self._json({"ok":False,"error":f"Erreur serveur : {exc}"},500)

    def log_message(self,fmt,*args):
        pass

def main():
    ap=argparse.ArgumentParser(description="Visualiseur local pour 42 push_swap")
    ap.add_argument("--push-swap",default="./push_swap")
    ap.add_argument("--host",default="127.0.0.1")
    ap.add_argument("--port",type=int,default=8765)
    args=ap.parse_args()

    root=Path.cwd().resolve()
    binary=Path(args.push_swap)
    if not binary.is_absolute():
        binary=(root/binary).resolve()

    srv=ThreadingHTTPServer((args.host,args.port),Handler)
    srv.push_swap=binary
    srv.repo_dir=root

    print(f"push_swap   : {binary}")
    print(f"visualiseur : http://localhost:{args.port}")
    print("Ctrl+C pour arrêter.")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nArrêt.")
    finally:
        srv.server_close()

if __name__=="__main__":
    main()
